from pydantic import BaseModel

_NOT_INDEPENDENCE_TEST_NOTE = (
    "This is not an independence test: exact_keywords are generated by an LLM from "
    "the question text, which is also ts_rank's input, so the two signals share their "
    "origin and partial agreement is guaranteed. It bounds how badly the keywords "
    "diverge from their own source; it cannot confirm they are right."
)


class KeywordQualityReport(BaseModel):
    """FR-10's measure of whether `exact_keywords` carry signal.

    `zero_match_share` and `document_frequency_distribution` are direct,
    self-contained measures of keyword quality that depend on no second signal.
    `hit_adherence_association` is the point-biserial correlation between the
    keyword-derived hit@k boolean and the FR-5 adherence score of the same question's
    top-1 comma — `not_an_independence_test_note` is a mandatory, constant statement
    of what that association cannot establish (see module docstring).
    """

    zero_match_share: float
    document_frequency_distribution: dict[str, int]
    hit_adherence_association: float
    not_an_independence_test_note: str = _NOT_INDEPENDENCE_TEST_NOTE
